preConditionHook:
// MomentumBeyondAtrMultiple -- Grimes A list (G02-06, G02-01, G03-15). Authored
// 2026-09-22 as new inputs on Momentum; split out as its own rule 2026-09-27 so
// Momentum stays the plain close[0] vs close[lookback] test.
//
// EL: upMove is set when close[lag + kk] > close[lag + kk + lookback] +
// minMoveAtr * WFSafe_AvgTrueRange(atrLookback) for any kk in 0..searchBars;
// downMove is the mirror on the other side of the margin.
//
// Three Grimes readings, one rule:
// - minMoveAtr / atrLookback (MomentumBeyondAtrMultiple, G02-06): "run up too far
//   too fast", the overextension that invites a countertrend scalp. His reading
//   is 2 ATRs over 3 bars, which is the default (lookback 3, minMoveAtr 2).
// - lag (PriorLegDirection, G02-01): the direction of the leg that ran INTO the
//   window. His accumulation read is this rule NEGATED on the long side, at
//   minMoveAtr 0 (the LaggedHigherHigh precedent for a lag input).
// - searchBars (ImpulseLegNetMove, G03-15, "trade only pullbacks preceded by
//   significant momentum", about 15 bars): the impulse leg need not end on this
//   bar, so the test is an ANY-OF over the last searchBars + 1 offsets.
//
// At lag = searchBars = minMoveAtr = 0 this is Momentum term for term: the loop
// runs once at offset 0 and adding 0.0 to a double is exact.
//
// ONE ATR READ FOR THE WHOLE SCAN, taken at the current bar: a lagged read of
// WFSafe_AvgTrueRange has no register row, and QuietBarCountInWindow's
// arrangement -- the series function called once in the hook, the scan an
// explicit loop -- is the corpus form. It is read unconditionally, even at
// minMoveAtr = 0, so MultiWalk's accumulator advances on exactly the same bars.
//
// WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term mean: seeded
// with a full sum on the study's first calculated bar, thereafter
// S += TrueRange; S -= TrueRange[Length]; as TWO statements (EasyLanguage
// evaluates S[1] + in - out left to right and folding it rounds differently),
// re-seeding when the length changes. AtrProfitTarget carries the notes.
//
// Deepest bar touched: max(lag + searchBars + lookback, atrLookback + 1).
//
// The flags and the accumulators are class members and persist across bars, so
// they are reset before use.
if (atrLen != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLookback;
moveMargin = minMoveAtr * atr;
upMove = false;
downMove = false;
for (int k = 0; k <= (int)searchBars; ++k) {
    if (el_gt(close[(int)lag + k], close[(int)lag + k + (int)lookback] + moveMargin)) upMove = true;
    if (el_lt(close[(int)lag + k], close[(int)lag + k + (int)lookback] - moveMargin)) downMove = true;
}
